import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            M = int(next(iterator))
            K = int(next(iterator))
        except StopIteration:
            break

        if N == 1 or M == 1:
            stones_per_cell = K
            results.append(stones_per_cell)
            continue

        if K == 1:
            results.append(1)
            continue

        dp = [[0] * (M + 1) for _ in range(N + 1)]
        dp[1][1] = K

        for r in range(1, N + 1):
            for c in range(1, M + 1):
                if r == 1 and c == 1:
                    continue
                up = dp[r-1][c] if r > 1 else 0
                left = dp[r][c-1] if c > 1 else 0

                if up == 0 and left == 0:
                    dp[r][c] = 0
                elif up == 0:
                    dp[r][c] = left // 2
                elif left == 0:
                    dp[r][c] = up // 2
                else:
                    total = up + left
                    dp[r][c] = (total + 1) // 2

        max_stones = 0
        for r in range(1, N + 1):
            if r == 1 or r == N:
                for c in range(2, M):
                    if dp[r][c] > max_stones:
                        max_stones = dp[r][c]
            else:
                for c in range(1, M + 1):
                    if c == 1 or c == M:
                        continue
                    if dp[r][c] > max_stones:
                        pass
                    else:
                        if dp[r][c] > max_stones:
                            max_stones = dp[r][c]

        if max_stones == 0:
            max_stones = 1

        results.append(max_stones)

    for res in results:
        print(res)

if __name__ == "__main__":
    solve()
